test('Writer generated entries parse in Windows PowerShell and its own ReadShare seal permits the production metadata ReadAllBytes', {skip:process.platform!=='win32'},()=>{
 const f=fixture({writer:true});try{
  const root=f.output(f.values('WRITER_CORE'));fs.mkdirSync(root);const current=path.join(root,'current-parser.ps1'),router=path.join(root,'router-parser.ps1'),probe=path.join(root,'self-read.ps1');
  fs.writeFileSync(current,f.values("renderCurrent('f'.repeat(40),'Writer')"));fs.writeFileSync(router,f.values("renderRouter('f'.repeat(40),'a'.repeat(64),'b'.repeat(64),'Writer')"));
  const text="param([string]$ExpectedSHA)\n$ErrorActionPreference='Stop'\n"+f.values('holdHelpers()')+"\ntry{Hold-B6 $PSCommandPath $ExpectedSHA;$copy=[IO.File]::ReadAllBytes($PSCommandPath);$hash=[Security.Cryptography.SHA256]::Create();try{$actual=[BitConverter]::ToString($hash.ComputeHash($copy)).Replace('-','').ToLowerInvariant()}finally{$hash.Dispose()};if($actual-cne$ExpectedSHA){throw 'SELF_READ_HASH_CHANGED'};foreach($leaf in @('current-parser.ps1','router-parser.ps1')){$errors=$null;$tokens=$null;[void][Management.Automation.Language.Parser]::ParseFile((Join-Path $PSScriptRoot $leaf),[ref]$tokens,[ref]$errors);if(@($errors).Count){throw 'WRITER_GENERATED_PARSE'}};'PASS'}finally{foreach($stream in $held){$stream.Dispose()}}";
  fs.writeFileSync(probe,text);const result=cp.execFileSync(path.join(process.env.SystemRoot??'C:/Windows','System32/WindowsPowerShell/v1.0/powershell.exe'),['-NoProfile','-NonInteractive','-File',probe,'-ExpectedSHA',sha(Buffer.from(text))],{windowsHide:true,encoding:'utf8',timeout:15000});assert.equal(result.trim(),'PASS');
 }finally{f.close();}
});


test('Writer V2 alone emits an authenticated initialization diagnostic and retains the original exception reference without message or cap output', {skip:process.platform!=='win32'},()=>{
 const f=fixture({writer:true});try{
  const tail=f.values('initializationFailureTail(true)'),legacy=f.values('initializationFailureTail()');
  assert(!legacy.includes('FailureDiagnostic'));assert(!tail.includes('.Message'));assert(!tail.includes('StackTrace'));assert(!tail.includes('.Data'));
  const file=path.join(f.temp,'wrapper-tail.ps1'),held=path.join(f.temp,'held.tmp');
  const ps=`$ErrorActionPreference='Stop';$held=@([IO.File]::Open('${held.replaceAll("'","''")}',[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None));$script:original=$null
function Get-Business5244VerifiedInitializationExitCode($Exception){if(![object]::ReferenceEquals($Exception,$script:original)){throw 'ORIGINAL_EXCEPTION_LOST'};return 73}
function Get-Business5244VerifiedInitializationFailureDiagnostic($Exception){if(![object]::ReferenceEquals($Exception,$script:original)){throw 'DIAGNOSTIC_EXCEPTION_LOST'};return [pscustomobject]@{code='FIXTURE_VALIDATOR_FAILED';sourceLeaf='start-business-5244-owned.ps1';sourceLine=32}}
try{try{throw 'PRIVATE_MESSAGE_MUST_NOT_LEAK'}catch{$script:original=$_.Exception;throw}}
${tail}`;
  fs.writeFileSync(file,ps);const result=cp.spawnSync(path.join(process.env.SystemRoot??'C:/Windows','System32/WindowsPowerShell/v1.0/powershell.exe'),['-NoProfile','-NonInteractive','-File',file],{encoding:'utf8',windowsHide:true,timeout:10000});
  assert.equal(result.status,73);assert.equal(result.stdout,'');const diagnostic=JSON.parse(result.stderr.trim());assert.deepEqual(diagnostic,{kind:'business-5244-initialization-restored',failure:{code:'FIXTURE_VALIDATOR_FAILED',sourceLeaf:'start-business-5244-owned.ps1',sourceLine:32}});assert(!result.stderr.includes('PRIVATE_MESSAGE'));const fd=fs.openSync(held,'r+');fs.closeSync(fd);fs.unlinkSync(held);fs.unlinkSync(file);
 }finally{f.close();}
});
